diff --git a/src/main/java/hotel/reservations/StandardRatePlan.java b/src/main/java/hotel/reservations/StandardRatePlan.java
new file mode 100644
index 0000000..d269640
--- /dev/null
+++ b/src/main/java/hotel/reservations/StandardRatePlan.java
@@ -0,0 +1,53 @@
+package hotel.reservations;
+
+import hotel.rooms.Room;
+import java.math.BigDecimal;
+import java.time.LocalDate;
+import java.time.Month;
+
+class StandardRatePlan implements RatePlanStrategy {
+
+    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
+
+    @Override
+    public void validate(ReservationData data) throws HotelException {
+        // Standard has no special validation beyond basic checks (done elsewhere)
+    }
+
+    @Override
+    public Price calculate(Room room, ReservationData data) {
+        int nights = 0;
+        BigDecimal subtotal = cents(BigDecimal.ZERO);
+        for (LocalDate night = data.checkIn(); night.isBefore(data.checkOut()); night = night.plusDays(1)) {
+            subtotal = subtotal.add(nightPrice(room, night));
+            nights++;
+        }
+        BigDecimal discount = cents(BigDecimal.ZERO);
+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+    }
+
+    @Override
+    public BigDecimal refundOnCancellation(Price price) {
+        return price.total();
+    }
+
+    private BigDecimal nightPrice(Room room, LocalDate night) {
+        BigDecimal nightlyRate = room.nightlyRate();
+        if (isHighSeason(night)) {
+            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
+        }
+        return cents(nightlyRate);
+    }
+
+    private static boolean isHighSeason(LocalDate date) {
+        Month month = date.getMonth();
+        return month == Month.JANUARY
+                || month == Month.FEBRUARY
+                || month == Month.JULY
+                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
+    }
+
+    protected static BigDecimal cents(BigDecimal value) {
+        return PriceCalculator.cents(value);
+    }
+}
diff --git a/src/main/java/hotel/reservations/WeekendPackageRatePlan.java b/src/main/java/hotel/reservations/WeekendPackageRatePlan.java
new file mode 100644
index 0000000..75a876f
--- /dev/null
+++ b/src/main/java/hotel/reservations/WeekendPackageRatePlan.java
@@ -0,0 +1,48 @@
+package hotel.reservations;
+
+import hotel.rooms.Room;
+import hotel.rooms.RoomType;
+import java.math.BigDecimal;
+import java.time.DayOfWeek;
+
+final class WeekendPackageRatePlan implements RatePlanStrategy {
+
+    @Override
+    public void validate(ReservationData data) throws HotelException {
+        int nights = 0;
+        var night = data.checkIn();
+        while (night.isBefore(data.checkOut())) {
+            nights++;
+            night = night.plusDays(1);
+        }
+
+        if (nights != 2) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package requires exactly 2 nights (Friday to Sunday)");
+        }
+
+        if (data.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package check-in must be on a Friday");
+        }
+    }
+
+    @Override
+    public Price calculate(Room room, ReservationData data) {
+        BigDecimal total = getPackagePrice(room.type());
+        return new Price(2, total, PriceCalculator.cents(BigDecimal.ZERO), total);
+    }
+
+    @Override
+    public BigDecimal refundOnCancellation(Price price) {
+        return PriceCalculator.cents(price.total().divide(new BigDecimal("2"), java.math.RoundingMode.HALF_EVEN));
+    }
+
+    private BigDecimal getPackagePrice(RoomType roomType) {
+        return switch (roomType) {
+            case STANDARD -> new BigDecimal("520.00");
+            case DELUXE -> new BigDecimal("820.00");
+            case SUITE -> new BigDecimal("1200.00");
+        };
+    }
+}
